    /** Character offsets into the source. */
    lazy val start: Option[Int] = _opt(json, "start").map(_num(json, "start", _).toInt)
    lazy val end: Option[Int]   = _opt(json, "end").map(_num(json, "end", _).toInt)

    private def _locField(which: String, name: String): Option[Int] =
      _opt(json, "loc").flatMap(loc => _opt(_obj(json, "loc", loc), which)).flatMap { pos =>
        _opt(_obj(json, s"loc.$which", pos), name).map(_num(json, s"loc.$which.$name", _).toInt)
      }

    /** 1-based line, 0-based column. */
    lazy val startLine: Option[Int]   = _locField("start", "line")
    lazy val startColumn: Option[Int] = _locField("start", "column")
    lazy val endLine: Option[Int]     = _locField("end", "line")
    lazy val endColumn: Option[Int]   = _locField("end", "column")

    lazy val leadingComments: Seq[Comment]  = _nodeSeq[Comment](json, "leadingComments")
    lazy val trailingComments: Seq[Comment] = _nodeSeq[Comment](json, "trailingComments")
    lazy val innerComments: Seq[Comment]    = _nodeSeq[Comment](json, "innerComments")

    /** Parser extras such as `raw`, `rawValue` or `parenthesized`, in source order. */
    lazy val extra: Map[String, Value] = _opt(json, "extra").fold(VectorMap.empty[String, Value])(extra =>
      VectorMap.from(_fields(_obj(json, "extra", extra)))
    )
    def isParenthesized: Boolean = extra.get("parenthesized").exists(_.boolOpt.contains(true))

    override def equals(other: Any): Boolean = other match {
      case node: BabelNode => (this eq node) || (json eq node.json)
      case _               => false
    }
    override def hashCode: Int    = System.identityHashCode(json)
    override def toString: String = {
      def position(name: String) = json.objOpt.flatMap(_.get(name)).flatMap(_.numOpt).fold("?")(_.toInt.toString)
      s"${_describe(json)}(${position("start")}-${position("end")})"
    }
  }

