  /** A node whose `type` is not a known Babel node type; only the generic `BabelNode` members are available. */
  final case class UnknownNode(json: Value)
      extends BabelNode
      with Accessor
      with Binary
      with Block
      with BlockParent
      with Class
      with Comment
      with CompletionStatement
      with Conditional
      with Declaration
      with EnumBody
      with EnumMember
      with ExportDeclaration
      with Expression
      with ExpressionWrapper
      with Flow
      with FlowBaseAnnotation
      with FlowDeclaration
      with FlowPredicate
      with FlowType
      with For
      with ForXStatement
      with Function
      with FunctionParameter
      with FunctionParent
      with Immutable
      with ImportOrExportDeclaration
      with JSX
      with LVal
      with Literal
      with Loop
      with Method
      with Miscellaneous
      with ModuleDeclaration
      with ModuleSpecifier
      with ObjectMember
      with Pattern
      with PatternLike
      with Private
      with Property
      with Pureish
      with Scopable
      with Standardized
      with Statement
      with TSBaseType
      with TSEntityName
      with TSType
      with TSTypeElement
      with Terminatorless
      with TypeScript
      with UnaryLike
      with UserWhitespacable
      with While
}
